{"command":"python3 - <<'PY'
import json
from collections import Counter
from pathlib import Path
findings = json.loads(Path('data/findings.json').read_text())
summary = json.loads(Path('reports/summary.json').read_text())
expected_keys = ['total_findings', 'severity_counts', 'open_finding_ids']
if list(summary.keys()) != expected_keys:
    raise SystemExit(f'Unexpected top-level keys/order: {list(summary.keys())}')
if not isinstance(summary['total_findings'], int):
    raise SystemExit('total_findings is not an integer')
expected_counts = {k: 0 for k in ['critical', 'high', 'medium', 'low']}
expected_counts.update(Counter(item['severity'] for item in findings))
if summary['total_findings'] != len(findings):
    raise SystemExit(f'total_findings mismatch: {summary["total_findings"]} != {len(findings)}')
if summary['severity_counts'] != expected_counts:
    raise SystemExit(f'severity_counts mismatch: {summary["severity_counts"]} != {expected_counts}')
expected_open = [item['id'] for item in findings if item.get('status') == 'open']
if summary['open_finding_ids'] != expected_open:
    raise SystemExit(f'open_finding_ids mismatch: {summary["open_finding_ids"]} != {expected_open}')
print('summary validation passed')
PY","workdir":"/testbed","timeout":120000}

